import {PlayerStage} from '../../../../core/stage/PlayerStage.js';
import {hubErrorMessage} from '../../../../core/gameHub.js';

// The onboarding form. The questions come from the server (generated by the AI agent, or built in). Each is
// free text ('Text'), pick one ('SingleChoice') or pick several ('MultiChoice'). Answers are private: they go to the
// server only, never to the other players. There is never a right answer.
export class TuringTownPlayerOnboarding extends PlayerStage {
    constructor() {
        // The form has text boxes, so ESC must not drop the player out.
        super('TuringTownPlayerOnboarding', {escapeLeaves: false});
    }

    build() {
        this.submitted = false;
        this.sending = false;

        this.title = this.addText('Tell us about you', {fontStyle: 'bold'});
        this.statusText = this.addText('', {align: 'center'});

        this.buildForm();
        this.listen(this.session, 'progress', () => this.showWaiting());
    }

    // A real HTML form, so phones bring up their keyboard and scroll to the field being typed in.
    buildForm() {
        const questions = this.session.state.data?.questions ?? [];

        // The questions scroll and Submit stays below them, so it never covers a choice.
        this.form = this.add.dom(0, 0, 'div');
        const wrap = this.form.node;
        wrap.className = 'tt-formwrap';
        const root = document.createElement('div');
        root.className = 'tt-form';
        wrap.append(root);
        // A focused field scrolls into view, so the keyboard does not hide it.
        root.addEventListener('focusin', e => e.target.scrollIntoView?.({block: 'nearest'}));

        // One entry per question: how to read its answer back out of the form.
        this.fields = questions.map((question, index) => {
            const box = document.createElement('fieldset');
            box.className = 'tt-q';

            // textContent only: the question text comes from the server.
            const legend = document.createElement('legend');
            const eyebrow = document.createElement('span');
            eyebrow.className = 'tt-eyebrow';
            eyebrow.textContent = `Q${index + 1} / ${questions.length}`;
            const text = document.createElement('span');
            text.className = 'tt-q-text';
            text.textContent = question.text;
            legend.append(eyebrow, text);
            box.append(legend);

            const field = question.kind === 'SingleChoice' || question.kind === 'MultiChoice'
                ? this.buildChoice(box, question)
                : this.buildText(box, question);

            root.append(box);
            return field;
        });

        const send = document.createElement('button');
        send.textContent = 'Submit';
        send.className = 'tt-submit';
        send.addEventListener('click', () => this.submit());
        wrap.append(send);
    }

    buildText(box, question) {
        const input = document.createElement('textarea');
        input.rows = 2;
        input.maxLength = 300;
        input.autocomplete = 'off';
        input.className = 'tt-input';
        box.append(input);

        return {
            question,
            read: () => ({questionId: question.id, text: input.value, optionIds: []}),
            problem: () => null
        };
    }

    // Radio rows for a single choice, checkbox rows for a multi choice. Each row is one big tap target.
    buildChoice(box, question) {
        const single = question.kind === 'SingleChoice';
        const max = single ? 1 : question.maxSelect;

        if (!single) {
            const hint = document.createElement('div');
            hint.textContent = question.minSelect === max ? `Pick ${max}` : `Pick ${question.minSelect} to ${max}`;
            hint.className = 'tt-hint';
            box.append(hint);
        }

        const rows = question.options.map((option, i) => {
            const row = document.createElement('label');
            row.className = 'tt-choice';

            const input = document.createElement('input');
            input.type = single ? 'radio' : 'checkbox';
            input.name = question.id;
            input.value = option.id;

            const caption = document.createElement('span');
            caption.textContent = `${String.fromCharCode(65 + i)}  ${option.text}`;

            row.append(input, caption);
            box.append(row);
            return {row, input};
        });

        const refresh = () => {
            const chosen = rows.filter(r => r.input.checked).length;
            for (const {row, input} of rows) {
                row.classList.toggle('on', input.checked);
                // Once enough are ticked, the rest cannot be.
                if (!single) input.disabled = !input.checked && chosen >= max;
                row.classList.toggle('off', input.disabled);
            }
        };
        for (const {input} of rows) input.addEventListener('change', refresh);
        refresh();

        const chosenIds = () => rows.filter(r => r.input.checked).map(r => r.input.value);

        return {
            question,
            read: () => ({questionId: question.id, text: '', optionIds: chosenIds()}),
            // A friendlier message than the server's. The server still checks everything.
            problem: number => {
                const n = chosenIds().length;
                if (n >= question.minSelect && n <= max) return null;
                return single ? `Pick one option for question ${number}.` : `Pick ${question.minSelect} to ${max} options for question ${number}.`;
            }
        };
    }

    async submit() {
        if (this.sending || this.submitted) return;

        for (const [i, field] of this.fields.entries()) {
            const problem = field.problem(i + 1);
            if (problem) {
                this.statusText.setText(problem);
                return;
            }
        }

        this.sending = true;
        this.statusText.setText('Sending...');

        try {
            await this.session.invoke('SubmitOnboarding', this.fields.map(field => field.read()));
            this.submitted = true;
            this.form.destroy();
            this.showWaiting();
            this.relayout();
        } catch (err) {
            this.statusText.setText(hubErrorMessage(err));
        } finally {
            this.sending = false;
        }
    }

    showWaiting() {
        if (!this.submitted) return;
        const {done, total} = this.session.progress;
        this.statusText.setText(`Answers sent!\nWaiting for everyone${total > 0 ? ` (${done}/${total})` : ''}`);
    }

    layout(m) {
        this.title.setPosition(m.cx, m.top + 130 * m.s).setFontSize(m.fs(40, 22));
        this.statusText.setPosition(m.cx, this.submitted ? m.cy : m.bottom - 50 * m.s)
            .setFontSize(m.fs(26, 16)).setWordWrapWidth(m.panelW - 60 * m.s);

        if (!this.submitted && this.form.active) {
            // Anchored under the title; a long form scrolls inside the card instead of running off the screen.
            const formTop = m.top + 175 * m.s;
            this.form.setOrigin(0.5, 0).setPosition(m.cx, formTop);
            this.form.node.style.width = `${m.panelW - 32}px`;
            this.form.node.style.maxHeight = `${Math.max(160, m.bottom - formTop - 70 * m.s)}px`;
            // Phaser caches the element's size for centring, so re-measure after changing it.
            this.form.updateSize();
        }
    }
}
